INSERT INTO gm.exercise_revision (exercise_id,revision,type,payload,rubric,normalization_version,provenance,review_status) VALUES ('81000000-0000-4000-8000-000001220171','1','choice','{"type":"choice","schemaVersion":1,"id":"81000000-0000-4000-8000-000001220171","revision":1,"targetId":"80000000-0000-4000-8000-000000012217","prompt":"Nach der Dürre diskutierten Betriebe der ___ über Wasserverbrauch auf Feldern und im Wald.","instruction":{"en":"Choose the noun or noun form that makes the sentence correct in context.","de":"Wähle das Nomen oder die Nomenform, die den Satz im Kontext richtig ergänzt."},"hint":{"en":"Both farming and forestry are affected by drought.","de":"Die Betriebe kümmern sich um Äcker und Wälder."},"options":[{"id":"0","text":"Land- und Forstwirtschaft"},{"id":"1","text":"Gastronomie"},{"id":"2","text":"Finanzverwaltung"},{"id":"3","text":"Medienbranche"}]}','{"normalizationVersion":"de-nfc-trim-v1","acceptedAnswers":[{"type":"choice","optionId":"0"}],"explanation":{"en":"The combined sector covers fields and forests.","de":"Der Begriff umfasst Betriebe mit land- und forstwirtschaftlichen Aufgaben."},"completedAnswer":{"schemaVersion":1,"parts":[{"text":"Nach der Dürre diskutierten Betriebe der Land- und Forstwirtschaft über Wasserverbrauch auf Feldern und im Wald.","emphasis":false}]}}','de-nfc-trim-v1','Original GPT-6 exercises based on pinned lexical facts apps/web/data/pos/nouns.jsonl:L1405 (a5c4577be8453008b031a5635ade1f452f840f98553db29501d7723b1d1717a7), 2026-10-29. Inherited examples not copied. Owner-authorized basic release by Owner direction 2026-11-04 at 2026-11-04T22:00:00Z; GPT-6 AI editorial/rubric checks; independent human review not required by owner. Authorization: Reviewed = editorially approved; only exact semantically rechecked corrections or nonblocking originals may be included.','approved');
