INSERT INTO gm.exercise_revision (exercise_id,revision,type,payload,rubric,normalization_version,provenance,review_status) VALUES ('81000000-0000-4000-8000-000001260011','1','choice','{"type":"choice","schemaVersion":1,"id":"81000000-0000-4000-8000-000001260011","revision":1,"targetId":"80000000-0000-4000-8000-000000012601","prompt":"Im Wartezimmer liegen mehrere Magazine zum Lesen. Was bedeutet „Magazine“ hier?","instruction":{"en":"Read the German context and choose the one accurate interpretation.","de":"Lies den deutschen Kontext und wähle die einzige zutreffende Bedeutung."},"hint":{"en":"Patients can browse printed issues.","de":"Man kann darin Artikel lesen."},"options":[{"id":"0","text":"Zeitschriften"},{"id":"1","text":"Lagerhallen"},{"id":"2","text":"Fernsehgeräte"},{"id":"3","text":"Aktenordner"}]}','{"normalizationVersion":"de-nfc-trim-v1","acceptedAnswers":[{"type":"choice","optionId":"0"}],"explanation":{"en":"Here Magazine means periodicals.","de":"Hier sind mit Magazinen Zeitschriften gemeint."},"completedAnswer":{"schemaVersion":1,"parts":[{"text":"Im Wartezimmer liegen mehrere Zeitschriften zum Lesen.","emphasis":false}]}}','de-nfc-trim-v1','Original GPT-6 draft based on pinned lexical facts apps/web/data/pos/nouns.jsonl:L1487 (cd89deadb43eb0d1feada3eac68930991c62f41c298930c5cc462323f46bcc4c), 2026-10-29; no inherited examples reused. Owner-authorized basic release by Owner direction 2026-11-04 at 2026-11-04T22:00:00Z; GPT-6 AI editorial/rubric checks; independent human review not required by owner. Authorization: Reviewed = editorially approved; only exact semantically rechecked corrections or nonblocking originals may be included.','approved');
