INSERT INTO gm.exercise_revision (exercise_id,revision,type,payload,rubric,normalization_version,provenance,review_status) VALUES ('81000000-0000-4000-8000-000001260021','1','choice','{"type":"choice","schemaVersion":1,"id":"81000000-0000-4000-8000-000001260021","revision":1,"targetId":"80000000-0000-4000-8000-000000012602","prompt":"Nach der Besprechung nehmen wir gemeinsam eine Mahlzeit ein. Was machen wir?","instruction":{"en":"Read the German context and choose the one accurate interpretation.","de":"Lies den deutschen Kontext und wähle die einzige zutreffende Bedeutung."},"hint":{"en":"The phrase „eine Mahlzeit einnehmen“ describes an everyday activity.","de":"Die Wendung „eine Mahlzeit einnehmen“ hat mit Essen zu tun."},"options":[{"id":"0","text":"Wir essen zusammen."},{"id":"1","text":"Wir planen einen Termin."},{"id":"2","text":"Wir schreiben ein Protokoll."},{"id":"3","text":"Wir räumen das Lager."}]}','{"normalizationVersion":"de-nfc-trim-v1","acceptedAnswers":[{"type":"choice","optionId":"0"}],"explanation":{"en":"The group is eating together.","de":"Die Gruppe isst gemeinsam."},"completedAnswer":{"schemaVersion":1,"parts":[{"text":"Nach der Besprechung essen wir gemeinsam.","emphasis":false}]}}','de-nfc-trim-v1','Original GPT-6 draft based on pinned lexical facts apps/web/data/pos/nouns.jsonl:L1489 (83146499b8baba15c92688566b8a8ee92ebf2c214ae04c43815f2638bb0f4fdc), 2026-10-29; no inherited examples reused. Owner-authorized basic release by Owner direction 2026-11-04 at 2026-11-04T22:00:00Z; GPT-6 AI editorial/rubric checks; independent human review not required by owner. Authorization: Reviewed = editorially approved; only exact semantically rechecked corrections or nonblocking originals may be included.','approved');
