INSERT INTO gm.exercise_revision (exercise_id,revision,type,payload,rubric,normalization_version,provenance,review_status) VALUES ('81000000-0000-4000-8000-000001260030','1','gap_choice','{"type":"gap_choice","schemaVersion":1,"id":"81000000-0000-4000-8000-000001260030","revision":1,"targetId":"80000000-0000-4000-8000-000000012603","prompt":"Weil die Rechnung seit sechs Wochen offen ist, verschickt die Firma eine ___.","instruction":{"en":"Choose the expression that correctly completes the German sentence.","de":"Wähle den Ausdruck, der den deutschen Satz richtig ergänzt."},"hint":{"en":"The customer has not paid yet.","de":"Die Kundin oder der Kunde hat noch nicht bezahlt."},"slots":[{"id":"noun","label":"Nomen oder Ausdruck","options":[{"id":"0","text":"Mahnung"},{"id":"1","text":"Gutschrift"},{"id":"2","text":"Einladung"},{"id":"3","text":"Bewerbung"}]}]}','{"normalizationVersion":"de-nfc-trim-v1","acceptedAnswers":[{"type":"gap_choice","selections":[{"slotId":"noun","optionId":"0"}]}],"explanation":{"en":"A Mahnung requests payment of an overdue amount.","de":"Eine Mahnung fordert zur Begleichung einer offenen Rechnung auf."},"completedAnswer":{"schemaVersion":1,"parts":[{"text":"Weil die Rechnung seit sechs Wochen offen ist, verschickt die Firma eine Mahnung.","emphasis":false}]}}','de-nfc-trim-v1','Original GPT-6 draft based on pinned lexical facts apps/web/data/pos/nouns.jsonl:L1490 (85211fb6083dd12d3311f0904ed24e42f9b57545a8b1327e56c62fc12ba33cd8), 2026-10-29; no inherited examples reused. Owner-authorized basic release by Owner direction 2026-11-04 at 2026-11-04T22:00:00Z; GPT-6 AI editorial/rubric checks; independent human review not required by owner. Authorization: Reviewed = editorially approved; only exact semantically rechecked corrections or nonblocking originals may be included.','approved');
